package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.locks.Condition;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

class SpinningReentrantLockTest {

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void contendedLockAdmitsOneHolderAtATime() throws Exception {
		SpinningReentrantLock lock = new SpinningReentrantLock();
		int threads = 8;
		int rounds = 20_000;
		int[] unguarded = new int[1];
		AtomicInteger holders = new AtomicInteger();
		AtomicInteger overlaps = new AtomicInteger();
		ExecutorService workers = Executors.newFixedThreadPool(threads);
		try {
			List<Future<?>> running = new ArrayList<>();
			for (int thread = 0; thread < threads; thread++) {
				boolean interruptible = thread % 2 == 0;
				running.add(workers.submit(() -> {
					for (int round = 0; round < rounds; round++) {
						if (interruptible) {
							lock.lockInterruptibly();
						} else {
							lock.lock();
						}
						try {
							if (holders.incrementAndGet() != 1) {
								overlaps.incrementAndGet();
							}
							unguarded[0]++;
							holders.decrementAndGet();
						} finally {
							lock.unlock();
						}
					}
					return null;
				}));
			}
			for (Future<?> worker : running) {
				worker.get(25, TimeUnit.SECONDS);
			}
		} finally {
			workers.shutdownNow();
		}
		assertEquals(0, overlaps.get());
		assertEquals(threads * rounds, unguarded[0]);
		assertFalse(lock.isLocked());
	}

	@Test
	void holderReentersAndReleasesOncePerAcquisition() throws Exception {
		SpinningReentrantLock lock = new SpinningReentrantLock();
		lock.lock();
		lock.lockInterruptibly();
		assertEquals(2, lock.getHoldCount());
		lock.unlock();
		assertTrue(lock.isHeldByCurrentThread());
		lock.unlock();
		assertFalse(lock.isLocked());
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void interruptibleAcquisitionReportsAnInterruptWhileTheLockIsHeld() throws Exception {
		SpinningReentrantLock lock = new SpinningReentrantLock();
		AtomicReference<Throwable> outcome = new AtomicReference<>();
		lock.lock();
		try {
			Thread waiter = new Thread(() -> {
				try {
					lock.lockInterruptibly();
					lock.unlock();
					outcome.set(new AssertionError("acquired a held lock"));
				} catch (InterruptedException interrupted) {
					outcome.set(interrupted);
				}
			});
			waiter.start();
			while (!lock.hasQueuedThread(waiter)) {
				Thread.onSpinWait();
			}
			waiter.interrupt();
			waiter.join(TimeUnit.SECONDS.toMillis(10));
		} finally {
			lock.unlock();
		}
		assertInstanceOf(InterruptedException.class, outcome.get());
		assertFalse(lock.isLocked());

		Thread.currentThread().interrupt();
		try {
			assertThrows(InterruptedException.class, lock::lockInterruptibly);
		} finally {
			Thread.interrupted();
		}
		assertFalse(lock.isLocked());
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void waiterOnAConditionIsWokenByItsSignal() throws Exception {
		SpinningReentrantLock lock = new SpinningReentrantLock();
		Condition changed = lock.newCondition();
		boolean[] ready = new boolean[1];
		AtomicInteger observed = new AtomicInteger();
		Thread waiter = new Thread(() -> {
			lock.lock();
			try {
				while (!ready[0]) {
					changed.awaitUninterruptibly();
				}
				observed.incrementAndGet();
			} finally {
				lock.unlock();
			}
		});
		waiter.start();
		while (true) {
			lock.lock();
			try {
				if (lock.hasWaiters(changed)) {
					ready[0] = true;
					changed.signalAll();
					break;
				}
			} finally {
				lock.unlock();
			}
			Thread.onSpinWait();
		}
		waiter.join(TimeUnit.SECONDS.toMillis(10));
		assertEquals(1, observed.get());
		assertFalse(lock.isLocked());
	}
}
